        msgs, tokenize=True, add_generation_prompt=True, **tmpl_kw,
    )
    ids = result["input_ids"] if hasattr(result, "keys") else list(result)
    if len(ids) > max_len:
        ids = ids[:max_len]
    return ids


def parse_prediction(text):
    if "</think>" in text:
